R.append((4028523,"अनानास क्रैनबेरी लोफ़",None,"12","रेसिपी का 1/12",
["2 बड़े अंडे","1 कप सफ़ेद चीनी","½ कप कैनोला तेल","½ छोटा चम्मच वनीला एक्सट्रैक्ट","1 ½ कप मैदा","1 छोटा चम्मच बेकिंग सोडा","¼ छोटा चम्मच पिसी सोंठ (अदरक)","¼ छोटा चम्मच पिसी दालचीनी","½ कप कुचला हुआ अनानास, पानी में डिब्बाबंद","1 कप जमी हुई क्रैनबेरी"],
["ओवन को 350°F पर पहले से गरम करें। लोफ़ पैन पर नॉन-स्टिक कुकिंग स्प्रे करें।","एक मिक्सिंग बाउल में अंडे, चीनी, तेल और वनीला डालें। मिलाने के लिए फेंटें।","एक अलग मिक्सिंग बाउल में मैदा, बेकिंग सोडा, सोंठ और दालचीनी को एक साथ छान लें।","सूखी सामग्री को अंडे के मिश्रण में डालें। अच्छी तरह मिलाएँ।","कुचला हुआ अनानास और जमी हुई क्रैनबेरी डालें और मिलाएँ।","अनानास का मिश्रण लोफ़ पैन (4\"× 8\") में डालें।","एक घंटा 15 मिनट बेक करें या जब तक लोफ़ के बीच में डाली टूथपिक साफ़ न निकले। ओवन से निकालें और ठंडा करें।","ढकें और कमरे के तापमान पर रखें।"],
[["अपने किडनी आहार में अनानास को शामिल करना","अपने किडनी आहार को रोचक बनाए रखने के लिए विभिन्न स्वादों और बनावटों वाले खाद्य पदार्थ चुनना महत्वपूर्ण है। फल स्वादों, फ़ाइबर और विटामिन का विकल्प देते हैं और पोषक तत्वों से भरपूर खाद्य पदार्थ हैं। हाल के अध्ययनों से पता चला है कि फलों और सब्ज़ियों में अधिक आहार किडनी के स्वास्थ्य के लिए अच्छा हो सकता है, लेकिन विशिष्ट सिफ़ारिशों के लिए और शोध की आवश्यकता है।\n\nअनानास आपके किडनी आहार के लिए कम पोटैशियम वाला एक उत्कृष्ट खाद्य पदार्थ है। ताज़े अनानास के टुकड़ों के एक कप के हिस्से में 200mg से कम पोटैशियम और सोडियम और फ़ॉस्फ़ोरस की न्यूनतम मात्रा होती है।\n\nअनानास को कई अलग-अलग व्यंजनों में शामिल किया जा सकता है। अनानास का उपयोग नाश्ते की टॉपिंग के रूप में या कम पोटैशियम वाले फल के कप के हिस्से के रूप में करें। उच्च पोटैशियम वाले टमाटरों की जगह एक अलग स्वाद और बनावट बनाने के लिए सैंडविच के ऊपर अनानास डालें। या अपने भोजन को और रोचक बनाने के लिए स्टर-फ़्राई व्यंजनों या स्लो कुकर के भोजन में अनानास डालें। मफ़िन या स्मूदी जैसी मिठाइयाँ ताज़े अनानास का स्वाद जोड़ने का एक और बेहतरीन तरीका हैं।"]],
["2 स्टार्च","2 वसा"]))
R.append((4035847,"बैंगन प्रोवेंसाल",None,"2","1/4 बैंगन + 1/3 कप चावल",
["1 मध्यम बैंगन","2 बड़े चम्मच जैतून का तेल","2 बड़े चम्मच जैतून का तेल","¼ कप प्याज़, कटा हुआ","½ कप लाल शिमला मिर्च, छोटे टुकड़ों में कटी हुई","½ कप पीली शिमला मिर्च, छोटे टुकड़ों में कटी हुई","¼ कप पानी","½ lb अतिरिक्त दुबला बीफ़ कीमा","2 लहसुन की कलियाँ, कटी हुई","2 छोटे चम्मच पैपरिका","1 बड़ा चम्मच वाइन सिरका","1 छोटा चम्मच सूखी अजवायन (ओरेगैनो)","¼ कप चेडर चीज़, कद्दूकस किया हुआ","½ कप सफ़ेद चावल, सूखे"],
["ओवन को 400°F पर पहले से गरम करें। बेकिंग ट्रे पर चर्मपत्र कागज़ (पार्चमेंट पेपर) बिछाएँ।","बैंगन को लंबाई में आधा काटें। हर आधे हिस्से की कटी सतह पर 1 बड़ा चम्मच जैतून का तेल लगाएँ। बैंगन के आधे हिस्सों को कटी तरफ़ नीचे करके ट्रे पर रखें और लगभग 35 मिनट बेक करें। पक जाने पर, बैंगन का भीतरी भाग नरम होना चाहिए जबकि बाहरी भाग अपना आकार बनाए रख सके।","एक नॉन-स्टिक पैन में मध्यम आँच पर जैतून का तेल गरम करें। प्याज़ और शिमला मिर्चें डालें और बीच-बीच में चलाते हुए 5 मिनट तलें। पानी डालें और तरल के वाष्पित होने तक पकाना जारी रखें। एक प्लेट में निकालकर एक तरफ़ रख दें।","उसी पैन में बीफ़ कीमा, लहसुन और पैपरिका डालें और मांस के भूरा होने तक तलें। सिरका, ओरेगैनो, चरण 3 का प्याज़ और शिमला मिर्चें डालें। सब कुछ मिलाएँ और पैन को आँच से उतारें।","चावल को पैकेट के निर्देशों के अनुसार पकाएँ।","बैंगन के आधे हिस्सों को ओवन से निकालें। चम्मच से गूदा सावधानी से निकालें, छिलका और अंदर गूदे की एक पतली परत बरकरार रखें ताकि बैंगन के आधे हिस्से भरावन को संभाल सकें।","चरण 4 के भरावन के मिश्रण में ¼ कप बैंगन का गूदा डालें और मिलाने के लिए चलाएँ। बचा हुआ बैंगन का गूदा फेंक दें।","भरावन को बैंगन के दोनों आधे हिस्सों में बाँट दें और ऊपर कद्दूकस किया हुआ चीज़ छिड़कें। बैंगन के आधे हिस्सों को कुछ मिनट के लिए ओवन में वापस रखें जब तक चीज़ पिघल न जाए।","बैंगन के आधे हिस्सों को 4 भागों में काटें और पके हुए चावल के साथ परोसें।"],
[["हैमबर्गर मांस के विकल्प","क्रोनिक किडनी रोग में सही मात्रा में प्रोटीन खाना अच्छे स्वास्थ्य को बनाए रखने के लिए महत्वपूर्ण है। किडनी की कार्यक्षमता घटी हुई कई लोगों को हृदय की समस्याएँ भी होती हैं और उन्हें हृदय-स्वस्थ आहार लेना चाहिए, जिसमें वसा और कोलेस्ट्रॉल कम हो। पंजीकृत आहार विशेषज्ञ के साथ काम करने से आपकी विशिष्ट प्रोटीन आवश्यकताओं और आपके स्वास्थ्य के लिए प्रोटीन के सर्वोत्तम विकल्पों को तय करने में मदद मिल सकती है। यदि आपको हृदय-स्वस्थ आहार लेना है, तो अतिरिक्त दुबला बीफ़ कीमा उपयोग करें। आप अन्य विकल्पों पर भी विचार कर सकते हैं। पौधे-आधारित प्रोटीन स्रोतों में पिसा हुआ टोफ़ू या सब्ज़ी बर्गर शामिल हैं। जीरा, लहसुन और काली मिर्च इन विकल्पों में उत्कृष्ट स्वाद जोड़ सकते हैं। उत्पाद के लेबल पढ़ें और सोडियम और पोटैशियम में सबसे कम वाले चुनें। चिकन, टर्की और सूअर का कीमा भी अच्छे प्रोटीन विकल्प हैं। तुलसी, लहसुन, सेज, थाइम और सूखी सेवरी कम सोडियम और कम पोटैशियम वाला स्वाद जोड़ने के लिए कुछ ही मसाले हैं। एक सेहतमंद विकल्प के रूप में बिना अतिरिक्त नमक वाला और कम वसा वाला ताज़ा कीमा चुनें।"]],
["2 मांस","1 1/2 स्टार्च","1 कम पोटैशियम वाली सब्ज़ी","1 वसा"]))
R.append((4035983,"सनी ब्रेकफ़ास्ट टार्ट",None,"4","रेसिपी का 1/4",
["4 बाज़ार से खरीदे पफ़ पेस्ट्री शेल","1 बड़ा चम्मच जैतून का तेल","½ कप लीक, धोया और कटा हुआ","1 कप बेबी पालक","1/8 छोटा चम्मच काली मिर्च","4 छोटे चम्मच लहसुन और जड़ी-बूटी वाला क्रीम चीज़*","4 अंडे"],
["एक छोटे स्किलेट में मध्यम आँच पर तेल गरम करें। लीक को लगभग 5 मिनट नरम होने तक भूनें। बेबी पालक डालें और मुरझाने तक भूनना जारी रखें। काली मिर्च डालें।","4 शेल को बेकिंग शीट पर रखें। हर शेल के तले पर 1 छोटा चम्मच लहसुन और जड़ी-बूटी वाला क्रीम चीज़ फैलाएँ। पालक और लीक के मिश्रण को चारों शेल में बाँट दें, अंडे के लिए गड्ढा बनाते हुए। गड्ढे में एक पूरा अंडा तोड़कर डालें।","15–20 मिनट या अंडे के सफ़ेद भाग के जमने तक बेक करें। तुरंत परोसें।"],
["* आप सामान्य क्रीम चीज़ का भी उपयोग कर सकते हैं और उसमें 1 छोटा चम्मच बारीक कटा लहसुन और ¼ छोटा चम्मच सोआ मिला सकते हैं","कृपया ध्यान दें: इस फ़ोटो के लिए शेफ़ ने बड़े शेल बनाने के लिए जमे हुए पफ़ पेस्ट्री आटे का उपयोग किया। यह आटा आमतौर पर बाज़ार से खरीदे शेल की तुलना में अधिक वसा वाला होता है।",["क्रीम चीज़ कम पोटैशियम वाला चीज़ विकल्प हो सकता है","अपने किडनी आहार का पालन करते समय उच्च पोटैशियम वाले खाद्य पदार्थों का सेवन घटाना महत्वपूर्ण है। चीज़ कई रेसिपी में पाया जाता है और आपके व्यंजन के स्वाद, रूप और बनावट में इज़ाफ़ा करता है। चीज़ कैल्शियम, प्रोटीन और विटामिन D देता है। हालाँकि, किडनी रोगी के लिए संयम आवश्यक है क्योंकि बहुत अधिक सेवन से सोडियम, फ़ॉस्फ़ोरस और पोटैशियम का सेवन अधिक हो जाता है। क्रीम चीज़ कम पोटैशियम वाला विकल्प है जिसे आप अपने भोजन के साथ उपयोग कर सकते हैं। एक बड़े चम्मच के हिस्से में लगभग 20mg पोटैशियम होता है। अपने हिस्से के आकार पर नज़र रखने से आप अपने किडनी आहार का पालन करते हुए इस खाद्य पदार्थ का आनंद ले सकते हैं। क्रीम चीज़ को एपेटाइज़र डिप के भरावन के रूप में, मिठाइयों और नाश्ते के व्यंजनों में मीठे व्यंजन के रूप में, फलों के सलाद में ड्रेसिंग के रूप में, साथ ही सैंडविच और मुख्य व्यंजनों के लिए स्प्रेड के रूप में आज़माएँ, जो इसे आपके किडनी आहार के लिए एक बहुत बहुमुखी खाद्य पदार्थ बनाता है।"]],
["1 मांस","1 स्टार्च","4 वसा"]))
R.append((4047168,"कम सोडियम वाली फ़िश फ़्राई","दक्षिणी क्षेत्र का एक पसंदीदा व्यंजन","2",None,
["3 ऑउंस सफ़ेद मछली के फ़िलेट (अपनी पसंद के, जैसे तिलापिया, कॉड, फ़्लाउंडर आदि), 2 प्रत्येक","1 बड़ा चम्मच बिना नमक का मक्खन या जैतून का तेल","मसाला मिश्रण: 1 छोटा चम्मच Mrs. Dash","ओरिजिनल और 1 छोटा चम्मच Mrs. Dash","गार्लिक और हर्ब सीज़निंग"],
["पैन में 1 बड़ा चम्मच बिना नमक का मक्खन या कैनोला तेल गरम करें।","मछली के फ़िलेट डालें (पहले पेपर टॉवल से सुखा लें)।","मछली के दोनों तरफ़ मसाला मिश्रण लगाएँ।","पैन में हर तरफ़ 3 मिनट तलें।","स्वादानुसार मछली के फ़िलेट पर ताज़ा नींबू निचोड़ें।"],
[],[]))
